// Shared Cuequill quill mark for the share cards (trade / month /
// achievement). Inlined as a base64 PNG data URI so the html-to-image
// capture is fully self-contained - it never has to fetch an external
// asset at snapshot time. The source is the metallic spearhead mark with
// the teal brand dot; its intrinsic size is 341x806 (ratio ~0.423).
export const QUILL_LOGO_SRC =
  "data:image/png;base64,";

export const QUILL_LOGO_RATIO = 341 / 806;
